const body = $input.first().json.body || $input.first().json || {};
const keyword = String(body.keyword || 'tu dong hoa n8n cho doanh nghiep nho').trim();
const audience = String(body.audience || 'Chu shop va ky su van hanh tai Viet Nam').trim();
const intent = String(body.intent || 'Commercial Investigation').trim();

const prompt = [
  `Ban la chuyen gia SEO ky thuat thi truong Viet Nam. Hay lap SEO Brief chuan E-E-A-T cho tu khoa: "${keyword}".`,
  `Doi tuong doc gia: ${audience}. Search Intent: ${intent}.`,
  'Tra ve DUY NHAT mot doi tuong JSON hop le voi cac truong:',
  'title (<=60 ky tu), metaDescription (<=155 ky tu), slug, primaryKeyword, secondaryKeywords (mang 5 tu khoa), outlineH2 (mang 5-7 muc H2 kem goi y H3), faq (mang 4 cau hoi), ctaAngle.'
].join('\n');

return [{ json: { keyword, audience, intent, prompt } }];

const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
const cleaned = raw.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
let brief = {};
try {
  brief = JSON.parse(cleaned);
} catch (err) {
  brief = { title: 'SEO Brief (Can kiem tra lai JSON)', metaDescription: cleaned.slice(0, 155), outlineH2: [], faq: [] };
}
const src = $('Chuan hoa Prompt SEO').first().json;
return [{
  json: {
    keyword: src.keyword,
    intent: src.intent,
    title: String(brief.title || src.keyword),
    metaDescription: String(brief.metaDescription || ''),
    slug: String(brief.slug || ''),
    secondaryKeywords: Array.isArray(brief.secondaryKeywords) ? brief.secondaryKeywords.join(', ') : '',
    outlineText: Array.isArray(brief.outlineH2) ? brief.outlineH2.map((h, i) => `${i + 1}. ${typeof h === 'string' ? h : JSON.stringify(h)}`).join('\n') : '',
    faqCount: Array.isArray(brief.faq) ? brief.faq.length : 0,
    createdAt: new Date().toISOString()
  }
}];

